code.cpp:
class Solution {
public:
    int maxPower(string s) {
        int best = 1;
        int cur = 1;
        for (int i = 1; i < (int)s.size(); i++) {
            if (s[i] == s[i - 1]) {
                cur++;
            } else {
                cur = 1;
            }
            if (cur > best) {
                best = cur;
            }
        }
        return best;
    }
};
